// Loader installs the graph named by a spec. An unknown name **errors**; it does not
// fall back to the default -- "I built the simple one, why does the UI show two"
// deserves an answer in the first second of startup, not a manual binary diff.
type Loader struct{ Spec string }

// Load returns the spec's components **already in start order** (see component.Loader).
func (l Loader) Load() ([]modules.Component, error) {
	name := l.Spec
	if name == "" {
		name = DefaultSpec
	}
	comps, ok := Specs()[name]
	if !ok {
		return nil, fmt.Errorf("no spec named %q (available: %s)", name, strings.Join(SpecNames(), ", "))
	}
	return comps, nil
}
